/** The source text of `free/sunburst-chart/categories.tsx`, as the Usage tab shows it. */
export default '/**\n * Stackra file contract:\n * Purpose: the "categories" demo of the native SunburstChart: a quarter\'s revenue by category, then by product.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0060 (light, dark, RTL); STA-1371.\n */\nimport { SunburstChart, useCatalogueText } from "@stackra/ui/native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { SUNBURST_CHART_DEMO_KEYS } from "#src/demos/free/sunburst-chart/sunburst-chart-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = SUNBURST_CHART_DEMO_KEYS.demo_free.sunburst_chart.categories;\n\n/** Each category and its products\' revenue. */\nconst TREE = [\n  [\n    "drinks",\n    [\n      ["coffee", 42_000],\n      ["tea", 9000],\n      ["juice", 6000],\n    ],\n  ],\n  [\n    "food",\n    [\n      ["bakery", 23_000],\n      ["sandwiches", 14_000],\n    ],\n  ],\n  [\n    "retail",\n    [\n      ["beans", 15_000],\n      ["merch", 8000],\n    ],\n  ],\n] as const;\n\n/** Sunburst chart: categories. */\nexport default function Categories() {\n  const t = useCatalogueText(MESSAGES.en);\n  return (\n    <SunburstChart\n      label={t(K.label)}\n      centerLabel={t(K.revenue)}\n      valueFormat={{ style: "currency", currency: "SAR", notation: "compact" }}\n      items={TREE.map(([key, children]) => ({\n        key,\n        label: t(K[key]),\n        children: children.map(([child, value]) => ({ key: child, label: t(K[child]), value })),\n      }))}\n    />\n  );\n}\n';
